CREATE TABLE "business_income" ("id" TEXT NOT NULL,"reference" TEXT NOT NULL,"loanId" TEXT NOT NULL,"amount" DECIMAL(18,2) NOT NULL,"recognizedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"description" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "business_income_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "business_income_reference_key" ON "business_income"("reference"); CREATE UNIQUE INDEX "business_income_loanId_key" ON "business_income"("loanId"); CREATE INDEX "business_income_recognizedAt_idx" ON "business_income"("recognizedAt"); ALTER TABLE "business_income" ADD CONSTRAINT "business_income_loanId_fkey" FOREIGN KEY("loanId") REFERENCES "loans"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
INSERT INTO "business_income" ("id","reference","loanId","amount","recognizedAt","description") SELECT 'bi-' || "id", 'HU-' || "loanNumber", "id", GREATEST(0, COALESCE("monthlyPayment",0) * "tenureMonths" - "principalAmount"), COALESCE("disbursedAt",NOW()), 'Pendapatan bunga pinjaman ' || "loanNumber" FROM "loans" WHERE "status"='ACTIVE' AND "monthlyPayment" IS NOT NULL;
